update `theme_customization_translations` set `options` = '{"html":"<div class=\"customization-section\" id=\"customization-section-video\">
    <div class=\"customization-container\" id=\"customization-container-main\">
        <!-- Video Section -->
        <div class=\"video-section\" id=\"customization-video-section\">
            <video class=\"video-player\" id=\"customization-video-player\" muted playsinline preload=\"metadata\" controls autoplay loop>
                <source src=\"https://www.zwitchoriginals.com/storage/theme/24/Customisationvideo.mp4\" type=\"video/mp4\">Your browser does not support the video tag.</video>
        </div>
        <!-- Content Section -->
        <div class=\"content-section\" id=\"customization-content-section\">
            <!-- Customization Card -->
            <div class=\"customization-card\" id=\"customization-card-main\">
                <div>
                    <div class=\"customization-title\" id=\"customization-card-title\">Customisation</div>
                    <div class=\"customization-subtitle\" id=\"customization-card-subtitle\">Personalize Your Order</div>
                </div>
            </div>
            <!-- Description Card -->
            <div class=\"description-card\" id=\"customization-description-card\">
                <div>
                    <!--<div class=\"description-title\" id=\"customization-description-title\">Description</div>-->
                    <div class=\"description-text\" id=\"customization-description-text\">Transform your vision into reality with our comprehensive customization options. From design modifications to size adjustments, we help you create the perfect product that reflects your unique style and preferences.</div> <a href=\"/customisation\" class=\"customization-btn\" id=\"customization-btn-start\">
                        Start Customizing
                    </a>

                </div>
            </div>
        </div>
    </div>
</div>","css":"/* Theme-aware component container */
 .customization-section {
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem;
    min-height: 100vh;
    display: flex;
    align-items: center;
    transition: all var(--transition-normal);
    margin-top: 50px;
}
.customization-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 2rem;
    width: 100%;
    min-height: 80vh;
}
/* Video Section */
 .video-section {
    background-color: #000000;
    border-radius: 12px;
    display: flex;
    align-items: center;
    justify-content: center;
    position: relative;
    overflow: hidden;
    cursor: pointer;
    transition: all var(--transition-normal);
    border: 2px solid #dddddd;
}
.video-section:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
}
.video-placeholder {
    text-align: center;
    color: #ffffff;
}
.video-play-button {
    font-size: 1.5rem;
    font-weight: 600;
    margin-bottom: 0.5rem;
    display: block;
}
.video-play-text {
    font-size: 1rem;
    opacity: 0.8;
}
.video-player {
    width: 100%;
    height: 100%;
}
.video-player.active {
    display: block;
}
/* Content Section */
 .content-section {
    display: flex;
    flex-direction: column;
    height:30vh;
}
.customization-card {
    background-color: var(--color-surface);
    border-radius: 12px;
    padding: 2rem;
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    transition: all var(--transition-normal), background-color var(--transition-normal), border-color var(--transition-normal);
}
.customization-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
    border-color: var(--color-border-light);
}
.customization-title {
    font-size: 52px;
    font-weight: 700;
    color: var(--color-text-primary);
    margin-bottom: 0.5rem;
    font-family: Unbounded !important;
    transition: color var(--transition-normal);
}
.customization-subtitle {
    font-size: 24px;
    color: var(--color-text-secondary);
    font-weight: 500;
    font-family: Urbanist !important;
    transition: color var(--transition-normal);
}
.description-card {
    background-color: var(--color-surface-secondary);
    border-radius: 12px;
    padding: 2rem;
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    transition: all var(--transition-normal), background-color var(--transition-normal), border-color var(--transition-normal);
}
.description-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
    border-color: var(--color-border-light);
}
.description-title {
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--color-text-primary);
    margin-bottom: 0.5rem;
    font-family: Unbounded !important;
    transition: color var(--transition-normal);
}
.description-text {
    font-size: 1rem;
    color: var(--color-text-secondary);
    line-height: 1.5;
    font-family: Urbanist !important;
    transition: color var(--transition-normal);
}
/* Responsive Design */
 @media (max-width: 768px) {
    .customization-container {
        grid-template-columns: 1fr;
        gap: 1.5rem;
    }
    .customization-section {
        padding: 1rem;
    }
    .customization-card, .description-card {
        padding: 1.5rem;
    }
    .customization-title, .description-title {
        font-size: 1.25rem;
    }
    .customization-subtitle, .description-text {
        font-size: 0.9rem;
    }
}
@media (max-width: 480px) {
    .customization-container {
        gap: 1rem;
    }
    .customization-card, .description-card {
        padding: 1rem;
    }
    .customization-title, .description-title {
        font-size: 1.125rem;
    }
}
/* Video Play Icon */
 .play-icon {
    width: 60px;
    height: 60px;
    background-color: rgba(255, 255, 255, 0.9);
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 1rem;
    transition: all var(--transition-normal);
}
.play-icon:hover {
    background-color: var(--color-accent);
    transform: scale(1.1);
}
.play-icon::after {
    content:'';
    width: 0;
    height: 0;
    border-left: 20px solid #000;
    border-top: 12px solid transparent;
    border-bottom: 12px solid transparent;
    margin-left: 4px;
}
/* Customization Button */
 .customization-btn {
    display: inline-block;
    background-color: #3e9ad9;
    color: white;
    padding: 0.75rem 1.5rem;
    border-radius: 8px;
    text-decoration: none;
    font-weight: 600;
    font-family: Urbanist !important;
    margin-top: 1.5rem;
    transition: all var(--transition-normal), background-color var(--transition-normal), border-color var(--transition-normal);
    border: 2px solid var(--color-primary);
}
.customization-btn:hover {
    background-color: var(--color-hover);
    border-color: var(--color-hover);
    transform: translateY(-2px);
    box-shadow: var(--shadow-md);
}
/* Christmas Theme Specific Styles */
[data-christmas=\"true\"] .video-section {
    background: linear-gradient(135deg, #1a1a1a 0%, #2d2d2d 100%);
    border-color: var(--color-accent);
}
[data-christmas=\"true\"] .customization-card {
    background: linear-gradient(135deg, var(--color-surface) 0%, var(--color-surface-secondary) 100%);
    border-color: var(--color-accent);
}
[data-christmas=\"true\"] .description-card {
    background: linear-gradient(135deg, var(--color-surface-secondary) 0%, var(--color-surface) 100%);
    border-color: var(--color-accent);
}
[data-christmas=\"true\"] .customization-btn {
    background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-accent) 100%);
    border-color: var(--color-accent);
}
/* Light Theme Specific Adjustments */
[data-theme=\"light\"] .video-section {
    border-color: var(--color-border-light);
}
[data-theme=\"light\"] .customization-card, [data-theme=\"light\"] .description-card {
    box-shadow: var(--shadow-sm);
}
/* Dark Theme Specific Adjustments */
[data-theme=\"dark\"] .video-section {
    border-color: #dddddd;
}
[data-theme=\"dark\"] .customization-card, [data-theme=\"dark\"] .description-card {
    box-shadow: var(--shadow-md);
}
.customization-btn:active {
    transform: translateY(0);
}"}' where `id` = 25

